import lombok.AllArgsConstructor;
import lombok.Data;

/**
 * One custom plugin setting within a config within a preset.
 */
@Data
@AllArgsConstructor
public class CustomSetting
{
	PluginSetting setting;
	PluginConfig parentConfig;
	PluginPreset parentPreset;
}

